diff --git a/test.js b/test.js
index e303a46..5781e05 100644
--- a/test.js
+++ b/test.js
@@ -193,6 +193,40 @@ test('clearQueue', async t => {
 	t.is(limit.pendingCount, 0);
 });

+test('clearQueue with default options leaves the active promise untouched and clears queued functions', async t => {
+	const limit = pLimit(1);
+
+	let activeRan = false;
+	let queuedRan = false;
+
+	const activePromise = limit(async () => {
+		await delay(100);
+		activeRan = true;
+	});
+
+	const queuedPromises = Array.from({length: 3}, () => limit(() => {
+		queuedRan = true;
+	}));
+
+	await Promise.resolve();
+	t.is(limit.activeCount, 1);
+	t.is(limit.pendingCount, 3);
+
+	limit.clearQueue();
+
+	t.is(limit.activeCount, 1);
+	t.is(limit.pendingCount, 0);
+
+	await activePromise;
+	t.true(activeRan);
+	t.false(queuedRan);
+
+	// The cleared queued promises never settle, so they must not be awaited directly.
+	// Confirm the public API surface used above (activeCount, pendingCount, clearQueue) is unchanged.
+	t.is(typeof limit.clearQueue, 'function');
+	t.is(queuedPromises.length, 3);
+});
+
 // Node.js 20 has a bug where DOMException is not properly handled by AVA's `throwsAsync`.
 const testClearQueueRejects = process.versions.node.startsWith('20.') ? test.skip : test;

diff --git a/test.js b/test.js
index e303a46..e853e93 100644
--- a/test.js
+++ b/test.js
@@ -193,6 +193,43 @@ test('clearQueue', async t => {
 	t.is(limit.pendingCount, 0);
 });

+test('clearQueue with default options leaves the active promise untouched and clears queued functions', async t => {
+	const limit = pLimit(1);
+
+	let queuedRan = false;
+
+	const activePromise = limit(async () => {
+		await delay(100);
+		return 'active';
+	});
+
+	// These never settle without `rejectOnClear`, so they must not be awaited.
+	Array.from({length: 3}, () => limit(() => {
+		queuedRan = true;
+	}));
+
+	await Promise.resolve();
+	t.is(limit.activeCount, 1);
+	t.is(limit.pendingCount, 3);
+
+	// Returns nothing, as documented.
+	t.is(limit.clearQueue(), undefined);
+
+	// Only the queue is discarded; the running function keeps going.
+	t.is(limit.activeCount, 1);
+	t.is(limit.pendingCount, 0);
+	t.is(await activePromise, 'active');
+
+	// Give the limiter a chance to resume anything that was not actually cleared.
+	await delay(10);
+	t.false(queuedRan);
+	t.is(limit.activeCount, 0);
+	t.is(limit.pendingCount, 0);
+
+	// The limiter is still usable afterwards.
+	t.is(await limit(() => 'after clear'), 'after clear');
+});
+
 // Node.js 20 has a bug where DOMException is not properly handled by AVA's `throwsAsync`.
 const testClearQueueRejects = process.versions.node.startsWith('20.') ? test.skip : test;
